text(await tools.exec_command({cmd:"OPENBLAS_NUM_THREADS=1 python - <<'PY'
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib
root=Path.cwd();out=root/'validation/ct96_cme_native_comparison';out.mkdir(exist_ok=True);base='ct96_w30';cases=[base,'ct96_w30_cme12','ct96_w30_cme24'];reports={};sources={};events={};coverage={}
for case in cases:
 p=root/f'validation/{case}_native/inhouse_native.json';reports[case]=json.loads(p.read_text());sources[str(p.relative_to(root))]=hashlib.sha256(p.read_bytes()).hexdigest()
for case in cases[1:]:
 p=root/f'validation/{case}_vs_ambient_native/comparison.json';c=json.loads(p.read_text());assert c['cases']==[case,base] and c['no_fitted_phase_or_amplitude'] is True
 sources[str(p.relative_to(root))]=hashlib.sha256(p.read_bytes()).hexdigest()
 for relative,wanted in c['source_files_sha256'].items():assert hashlib.sha256((root/relative).read_bytes()).hexdigest()==wanted
 t=c['monitors']['stereo_a']['fixed_stream_timing'];events[case]=dict(speed=t['speed_km_s'][case],density_peak=t['density_peaks'][case]);events.setdefault('observed',dict(speed=t['speed_km_s']['observed'],density_peak=t['density_peaks']['observed']));events.setdefault(base,dict(speed=t['speed_km_s'][base],density_peak=t['density_peaks'][base]))
 for monitor,m in c['monitors'].items():
  item={k:m[k] for k in ['common_finite_positive_all_quantity_hours','common_first_label_utc','common_last_label_utc']}
  assert monitor not in coverage or coverage[monitor]==item;coverage[monitor]=item
metrics={monitor:{case:reports[case]['cases'][case][monitor]['inhouse'] for case in cases} for monitor in coverage}
